export type FeatureDomain = (typeof ATLAS_DOMAINS)[number]
export type FeatureMaturity = 'live' | 'preview' | 'planned' | 'inactive'

export type AtlasFeature = {
  id: string
  name: string
  domain: FeatureDomain
  maturity: FeatureMaturity
  summary: string
  route: string
  tags: string[]
  icon?: AppIconName
}

type AtlasSeed = Omit<AtlasFeature, 'id' | 'domain' | 'route' | 'icon'> & {
  slug: string
  route?: string
  icon?: AppIconName
}

