export const FEATURE_ATLAS: AtlasFeature[] = ATLAS_DOMAINS.flatMap(domain =>
  atlasSections[domain].map(feature => ({
    id: `${domain}.${feature.slug}`,
    domain,
    route: feature.route ?? ROUTE_BY_DOMAIN[domain],
    icon: feature.icon ?? ICON_BY_DOMAIN[domain],
    name: feature.name,
    maturity: feature.maturity,
    summary: feature.summary,
    tags: feature.tags,
  })),
)

const EMPTY_MATURITY_COUNTS: Record<FeatureMaturity, number> = {
  live: 0,
  preview: 0,
  planned: 0,
  inactive: 0,
}

export const ATLAS_MATURITY_COUNTS = FEATURE_ATLAS.reduce<Record<FeatureMaturity, number>>(
  (counts, feature) => {
    counts[feature.maturity] += 1
    return counts
  },
  {...EMPTY_MATURITY_COUNTS},
)

export function atlasCountsByMaturity(): Record<FeatureMaturity, number> {
  return {...ATLAS_MATURITY_COUNTS}
}

export function atlasByDomain(domain?: FeatureDomain): AtlasFeature[] {
  if (!domain) return FEATURE_ATLAS
  return FEATURE_ATLAS.filter(feature => feature.domain === domain)
}

export function atlasSearch(q: string): AtlasFeature[] {
  const query = q.trim().toLowerCase()
  if (!query) return FEATURE_ATLAS
  const terms = query.split(/\s+/)
  return FEATURE_ATLAS.filter(feature => {
    const haystack = [
      feature.name,
      feature.domain,
      ATLAS_DOMAIN_LABELS[feature.domain],
      feature.maturity,
      feature.summary,
      feature.route,
      ...feature.tags,
    ]
      .join(' ')
      .toLowerCase()
    return terms.every(term => haystack.includes(term))
  })
}

export function isFeatureDomain(value: string | undefined): value is FeatureDomain {
  return ATLAS_DOMAINS.includes(value as FeatureDomain)
}

export function isFeatureMaturity(value: string | undefined): value is FeatureMaturity {
  return value === 'live' || value === 'preview' || value === 'planned' || value === 'inactive'
}
